CREATE TABLE scheduling_settings(id boolean PRIMARY KEY DEFAULT true CHECK(id),travel_gap_minutes integer NOT NULL DEFAULT 30 CHECK(travel_gap_minutes BETWEEN 0 AND 1440),version integer NOT NULL DEFAULT 1 CHECK(version>0));
INSERT INTO scheduling_settings(id) VALUES(true);
CREATE TABLE venues(id text PRIMARY KEY,name text NOT NULL CHECK(length(btrim(name)) BETWEEN 1 AND 100),address text NOT NULL CHECK(length(btrim(address)) BETWEEN 1 AND 300),region text NOT NULL CHECK(region IN ('hk-island','nt-west-islands','kowloon-east','nt-east','kowloon-west')),active boolean NOT NULL DEFAULT true,version integer NOT NULL DEFAULT 1 CHECK(version>0));
CREATE TABLE class_types(id text PRIMARY KEY,name text NOT NULL CHECK(length(btrim(name)) BETWEEN 1 AND 100),level text NOT NULL CHECK(length(btrim(level)) BETWEEN 1 AND 100),active boolean NOT NULL DEFAULT true,version integer NOT NULL DEFAULT 1 CHECK(version>0));
CREATE TABLE class_series(id text PRIMARY KEY,venue_id text NOT NULL REFERENCES venues(id),class_type_id text NOT NULL REFERENCES class_types(id),coach_id text NOT NULL REFERENCES users(id),start_date date NOT NULL,end_date date NOT NULL,weekday integer NOT NULL CHECK(weekday BETWEEN 1 AND 7),start_time time NOT NULL,end_time time NOT NULL,capacity integer NOT NULL CHECK(capacity>0),created_at timestamptz NOT NULL DEFAULT now(),CHECK(end_date>=start_date),CHECK(end_time>start_time));
CREATE TABLE class_sessions(id text PRIMARY KEY,venue_id text NOT NULL REFERENCES venues(id),class_type_id text NOT NULL REFERENCES class_types(id),coach_id text NOT NULL REFERENCES users(id),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,capacity integer NOT NULL CHECK(capacity>0),series_id text REFERENCES class_series(id),version integer NOT NULL DEFAULT 1 CHECK(version>0),CHECK(ends_at>starts_at));
CREATE INDEX class_sessions_coach_time ON class_sessions(coach_id,starts_at,ends_at);
CREATE INDEX class_sessions_start ON class_sessions(starts_at);
CREATE INDEX class_sessions_series ON class_sessions(series_id);
